return function(params,ctx)
 local a=ctx.run_agent{name="extract",prompt=params.prompts.extract,model=params.models.extract,input=ctx.input,tools={"read_invoice"},controls={temperature=0,max_tokens=500}}
 if a.output==nil then error("extractor did not deliver") end
 local b=ctx.run_agent{name="review",prompt=params.prompts.review,model=params.models.review,input=a.output,tools={},controls={temperature=0,max_tokens=500}}
 return {answer=b.output,extraction=a.output}
end

